package com.group01.assessment.api.dto.response;
import com.group01.assessment.application.result.AttemptStructureResult; import java.util.List; import java.util.UUID;
public record AttemptStructureResponse(List<Section> sections){ public record Section(UUID id,UUID contentSectionId,int sortOrder,String snapshot,List<Item> items){} public record Item(UUID id,UUID questionVersionId,int sortOrder,String questionSnapshot,String answerSnapshot,String knowledgeSnapshot){} public static AttemptStructureResponse from(AttemptStructureResult r){return new AttemptStructureResponse(r.sections().stream().map(s->new Section(s.id(),s.contentSectionId(),s.sortOrder(),s.snapshot(),s.items().stream().map(i->new Item(i.id(),i.questionVersionId(),i.sortOrder(),i.questionSnapshot(),i.answerSnapshot(),i.knowledgeSnapshot())).toList())).toList());} }
